import {BAD,GOOD,rollout,evaluate,initial} from './rl.js';
import {drawCafe} from './draw.js';
import {parseVote,tallyVotes} from './votes.js';
import {TwitchChat,authorizationUrl} from './twitch.js';
const $=id=>document.getElementById(id),rules=['pickup','delivery','movement'];
const overlay=new URLSearchParams(location.search).has('overlay');if(overlay)document.body.classList.add('overlay');
let current=null,baseline=null,worker=null,frame=0,frames=[{state:initial(),event:'Opening the café…'}],originalFrames=null,paused=false,lastStep=0,startIndex=0;
let votes=new Map(),voteEnd=0,voteTimer=null;
const starts=[[3,2],[0,4],[6,0],[0,0],[6,4]];
const channel=typeof BroadcastChannel==='function'?new BroadcastChannel('raised-this-cafe'):null;
const readWeights=()=>Object.fromEntries(rules.map(rule=>[rule,Number($(rule).value)]));
function setWeights(weights){for(const rule of rules){$(rule).value=weights[rule];$(rule+'-value').value='+'+weights[rule];}}
function setTraining(active){for(const id of ['train','repair','reset','vote-open'])$(id).disabled=active;for(const rule of rules)$(rule).disabled=active;}
function validPolicy(policy){return policy?.q?.length===70&&policy.q.every(row=>row.length===6&&row.every(Number.isFinite))&&rules.every(rule=>Number.isFinite(policy.weights?.[rule]));}
function persist(){const snapshot={version:1,current,baseline};try{localStorage.setItem('raised-this-experiment',JSON.stringify(snapshot));}catch{}channel?.postMessage({type:'snapshot',...snapshot});}
function rebuild(){if(!current)return;const [x,y]=starts[startIndex];frames=rollout(current.q,current.weights,initial(x,y)).frames;originalFrames=baseline?rollout(baseline.q,baseline.weights,initial(x,y)).frames:null;frame=0;paused=false;$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pause replay');render();}
function updateResults(){if(!current||!baseline)return;const b=evaluate(baseline.q,baseline.weights),m=evaluate(current.q,current.weights);$('baseline-served').textContent=b.deliveries.toFixed(1);$('current-served').textContent=m.deliveries.toFixed(1);$('baseline-pickups').textContent=b.pickups.toFixed(1);$('current-pickups').textContent=m.pickups.toFixed(1);
 const improved=m.deliveries>b.deliveries;
 $('finding-title').textContent=improved?'Same robot. Better incentives.':'The robot got paid. Nobody got coffee.';
 $('finding-copy').textContent=improved?`The original policy served ${b.deliveries.toFixed(1)} customers per shift. Your new policy serves ${m.deliveries.toFixed(1)}. The difference is what you chose to reward.`:'The robot has learned an efficient way to earn points. Try rewarding completed deliveries instead of cup pickups, then train a fresh policy.';
 $('policy-badge').textContent=improved?'Repaired policy':'Original experiment';
}
function train(weights){if(worker||overlay)return;closeVoting(false);setTraining(true);$('policy-badge').textContent='Learning…';$('training-status').textContent='Training a fresh Q-table…';$('progress').value=0;const trainingWorker=new Worker('./train-worker.js',{type:'module'});worker=trainingWorker;
 trainingWorker.onmessage=({data})=>{if(data.type==='progress'){$('progress').value=data.episode;$('training-status').textContent=`${data.episode.toLocaleString()} / ${data.total.toLocaleString()} episodes · seed 42`;}
 if(data.type==='complete'){current={q:data.q,weights:data.weights,seed:data.seed,total:data.total,history:data.history};if(!baseline)baseline=structuredClone(current);trainingWorker.terminate();worker=null;setTraining(false);$('training-status').textContent='6,000 episodes complete · frozen replay · seed 42';updateResults();persist();rebuild();}};
 trainingWorker.onerror=event=>{trainingWorker.terminate();worker=null;setTraining(false);$('training-status').textContent='Training failed: '+event.message;$('policy-badge').textContent='Training error';};trainingWorker.postMessage({weights,seed:42,total:6000});
}
function render(){const active=frames[frame],s=active.state;drawCafe($('cafe'),frames,frame,originalFrames,$('compare').checked);$('reward').textContent=s.reward.toFixed(1);$('deliveries').replaceChildren(document.createTextNode(s.delivered+' '),Object.assign(document.createElement('em'),{textContent:'/ shift'}));$('pickups').textContent=s.pickups;$('action-label').textContent=active.event;$('step-label').textContent=`SHIFT ${String(s.t).padStart(2,'0')} / 90`;$('verdict').textContent=s.pickups>5&&!s.delivered?'A lot of work. Zero coffee.':s.delivered?'Coffee is reaching actual people.':'The incentives are in charge.';}
function tick(time){if(!paused&&current&&time-lastStep>Number($('speed').value)){lastStep=time;if(frame<frames.length-1){frame++;render();}else if(time-lastStep>=0){paused=true;$('pause').textContent='▶';$('pause').setAttribute('aria-label','Play replay');}}requestAnimationFrame(tick);}requestAnimationFrame(tick);
for(const rule of rules)$(rule).addEventListener('input',()=>{$(rule+'-value').value='+'+$(rule).value;$('training-status').textContent='Rules edited. Train to apply them; the replay keeps its saved incentives.';});
$('train').onclick=()=>train(readWeights());$('repair').onclick=()=>{setWeights(GOOD);train({...GOOD});};$('reset').onclick=()=>{if(!baseline)return;setWeights(BAD);current=structuredClone(baseline);$('compare').checked=false;startIndex=0;updateResults();persist();rebuild();$('training-status').textContent='Original policy restored · frozen replay';};
$('replay').onclick=()=>{rebuild();channel?.postMessage({type:'replay'});};$('compare').onchange=render;$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Play replay':'Pause replay');};
$('new-start').onclick=()=>{startIndex=(startIndex+1)%starts.length;rebuild();channel?.postMessage({type:'start',index:startIndex});};
$('export').onclick=()=>{if(!current)return;const data={version:1,name:'Chat, You Raised This',algorithm:{name:'Tabular Q-learning',alpha:0.18,gamma:0.94,epsilon:'0.9 linearly decaying to 0.07',timeLimit:'90-step truncation with bootstrapping'},original:baseline,current,metrics:{original:evaluate(baseline.q,baseline.weights),current:evaluate(current.q,current.weights)}};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='cafe-experiment.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function openVoting(){votes=new Map();voteEnd=Date.now()+30000;$('vote-open').textContent='Close & apply';voteTimer=setInterval(()=>{if(Date.now()>=voteEnd)closeVoting();else $('vote-status').textContent=`${Math.ceil((voteEnd-Date.now())/1000)}s left · ${votes.size} viewer votes · one choice per viewer`;},250);$('vote-status').textContent='30s left · 0 votes. Chat can vote now.';}
function closeVoting(apply=true){if(!voteEnd)return;clearInterval(voteTimer);voteEnd=0;$('vote-open').textContent='Open 30s vote';if(apply&&votes.size){setWeights(tallyVotes(votes,readWeights()));$('vote-status').textContent=`Applied ${votes.size} viewer votes. Ties choose the lower value. Train to teach this recipe.`;$('training-status').textContent='Chat recipe ready. Train to apply.';}else $('vote-status').textContent='Voting closed. No reward changes applied.';}
function chatVote(message){const vote=parseVote(message.text);if(!vote||!voteEnd||Date.now()>=voteEnd||worker)return;votes.set(message.user,vote);$('vote-status').textContent=`${Math.max(0,Math.ceil((voteEnd-Date.now())/1000))}s left · ${votes.size} viewer votes · latest: ${vote.rule} +${vote.value}`;}
$('vote-open').onclick=()=>voteEnd?closeVoting():openVoting();$('vote-demo').onclick=()=>{if(worker)return;if(!voteEnd)openVoting();chatVote({user:'local-demo-viewer',text:'!reward delivery 8'});};
if(channel)channel.onmessage=({data})=>{if(data.type==='request'&&!overlay&&current)persist();if(overlay&&data.type==='snapshot'&&validPolicy(data.current)&&validPolicy(data.baseline)){current=data.current;baseline=data.baseline;updateResults();rebuild();}if(overlay&&data.type==='replay')rebuild();if(overlay&&data.type==='start'){startIndex=data.index;rebuild();}};
try{const saved=JSON.parse(localStorage.getItem('raised-this-experiment'));if(saved?.version===1&&validPolicy(saved.current)&&validPolicy(saved.baseline)){current=saved.current;baseline=saved.baseline;setWeights(current.weights);updateResults();rebuild();$('progress').value=6000;$('training-status').textContent='Saved experiment restored · frozen replay';}}catch{}
if(!current&&!overlay)train({...BAD});else if(overlay&&!current)$('action-label').textContent='Open the main game in another tab to sync the overlay.';if(overlay)channel?.postMessage({type:'request'});render();
// Only non-secret app settings and CSRF state are stored. OAuth tokens stay in memory.
const redirect=location.origin+location.pathname;$('redirect-url').textContent=redirect;
$('client-id').value=sessionStorage.getItem('twitch-client')||'';$('channel').value=sessionStorage.getItem('twitch-channel')||'';
const twitch=new TwitchChat(chatVote,(status,error=false)=>{$('connection').textContent='● '+status;$('connection').style.color=error?'#ffad9d':'#d3f687';if(error)$('twitch-error').textContent=status;});
$('twitch-open').onclick=()=>$('twitch-dialog').showModal();$('twitch-close').onclick=()=>$('twitch-dialog').close();$('twitch-disconnect').onclick=()=>{twitch.disconnect();$('connection').textContent='● Local playground';$('connection').style.color='';$('twitch-dialog').close();};
$('twitch-form').onsubmit=event=>{event.preventDefault();const clientId=$('client-id').value.trim(),name=$('channel').value.trim().toLowerCase(),state=crypto.randomUUID();sessionStorage.setItem('twitch-state',state);sessionStorage.setItem('twitch-client',clientId);sessionStorage.setItem('twitch-channel',name);location.href=authorizationUrl(clientId,redirect,state);};
const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('access_token')||fragment.has('error')){history.replaceState(null,'',location.pathname+location.search);const expected=sessionStorage.getItem('twitch-state');sessionStorage.removeItem('twitch-state');if(!expected||fragment.get('state')!==expected){$('twitch-error').textContent='Authorization state did not match. Please connect again.';$('twitch-dialog').showModal();}else if(fragment.has('error')){$('twitch-error').textContent=fragment.get('error_description')||'Authorization cancelled.';$('twitch-dialog').showModal();}else twitch.connect({token:fragment.get('access_token'),clientId:$('client-id').value,channel:$('channel').value}).catch(error=>{$('twitch-error').textContent=error.message;$('connection').textContent='● Local playground';$('twitch-dialog').showModal();});}
window.addEventListener('beforeunload',()=>{twitch.disconnect();worker?.terminate();channel?.close();});
